export default "<!doctype html>\n<html lang=\"en\">\n<head>\n  <meta charset=\"utf-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  <meta name=\"robots\" content=\"noindex,nofollow,noarchive,nosnippet,noimageindex\">\n  <meta name=\"googlebot\" content=\"noindex,nofollow,noarchive,nosnippet,noimageindex\">\n  <meta name=\"bingbot\" content=\"noindex,nofollow,noarchive,nosnippet,noimageindex\">\n  <meta name=\"referrer\" content=\"no-referrer\">\n  <title>Simple AI Field Loops</title>\n  <style>\n    :root {\n      --bg: #eef4f2;\n      --paper: #ffffff;\n      --ink: #111918;\n      --muted: #50605c;\n      --line: #cad9d4;\n      --line-strong: #78968c;\n      --teal: #0f6b58;\n      --blue: #155f8c;\n      --red: #9b3745;\n      --gold: #8b6c13;\n      --violet: #5a4f92;\n      --code: #172320;\n      --code-soft: #22322e;\n      --code-ink: #f4fbf8;\n      --max: 1180px;\n      --measure: 76ch;\n      --radius: 8px;\n    }\n\n    * { box-sizing: border-box; }\n    html { scroll-behavior: smooth; -webkit-text-size-adjust: 100%; }\n    body {\n      margin: 0;\n      color: var(--ink);\n      background:\n        linear-gradient(180deg, rgba(255,255,255,0.76), rgba(255,255,255,0) 360px),\n        var(--bg);\n      font-family: Avenir Next, Inter, Segoe UI, Helvetica Neue, Arial, sans-serif;\n      line-height: 1.56;\n    }\n    a { color: var(--blue); text-underline-offset: 0.17em; }\n    a:hover { color: var(--red); }\n    code, pre, kbd { font-family: SFMono-Regular, Menlo, Consolas, Liberation Mono, monospace; }\n\n    .page {\n      width: min(var(--max), calc(100% - 32px));\n      margin: 0 auto;\n      padding: 28px 0 56px;\n    }\n    header {\n      display: grid;\n      grid-template-columns: minmax(0, 1.05fr) minmax(280px, 0.58fr);\n      gap: 26px;\n      align-items: end;\n      padding: 20px 0 26px;\n      border-bottom: 1px solid var(--line-strong);\n    }\n    .eyebrow {\n      margin: 0 0 10px;\n      color: var(--teal);\n      font-size: 0.78rem;\n      font-weight: 800;\n      text-transform: uppercase;\n    }\n    h1, h2, h3, h4 {\n      margin: 0;\n      font-family: Georgia, Iowan Old Style, Times New Roman, serif;\n      line-height: 1.09;\n    }\n    h1 {\n      max-width: 15ch;\n      font-size: 4.85rem;\n      font-weight: 700;\n    }\n    .dek {\n      max-width: var(--measure);\n      margin: 18px 0 0;\n      color: var(--muted);\n      font-size: 1.16rem;\n    }\n    .status-card {\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: rgba(255,255,255,0.78);\n      padding: 16px 18px;\n    }\n    .status-card dl {\n      display: grid;\n      grid-template-columns: 102px 1fr;\n      gap: 9px 12px;\n      margin: 0;\n    }\n    .status-card dt {\n      color: var(--muted);\n      font-weight: 800;\n    }\n    .status-card dd { margin: 0; }\n    nav {\n      position: sticky;\n      top: 0;\n      z-index: 5;\n      margin: 0 -8px;\n      padding: 12px 8px;\n      border-bottom: 1px solid var(--line);\n      background: rgba(238,244,242,0.94);\n      backdrop-filter: blur(10px);\n    }\n    nav ul {\n      display: flex;\n      flex-wrap: wrap;\n      gap: 7px;\n      margin: 0;\n      padding: 0;\n      list-style: none;\n    }\n    nav a {\n      display: block;\n      padding: 6px 9px;\n      border: 1px solid var(--line);\n      border-radius: 6px;\n      color: var(--ink);\n      background: rgba(255,255,255,0.74);\n      font-size: 0.9rem;\n      text-decoration: none;\n    }\n\n    main {\n      display: grid;\n      gap: 36px;\n      min-width: 0;\n      padding-top: 30px;\n    }\n    section {\n      min-width: 0;\n      padding: 30px 0;\n      border-bottom: 1px solid var(--line);\n    }\n    section > h2 {\n      max-width: 22ch;\n      margin-bottom: 16px;\n      font-size: 2.35rem;\n    }\n    h3 { font-size: 1.2rem; }\n    .lead {\n      max-width: min(var(--measure), 100%);\n      color: var(--muted);\n      font-size: 1.06rem;\n    }\n    .grid {\n      display: grid;\n      grid-template-columns: repeat(12, minmax(0, 1fr));\n      gap: 14px;\n      margin-top: 18px;\n    }\n    .card, details, .callout {\n      min-width: 0;\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: var(--paper);\n      padding: 16px;\n    }\n    .card h3, details h3, .callout h3 {\n      margin-bottom: 8px;\n      font-size: 1.14rem;\n    }\n    .card p, .card li, details p, details li, .callout p, .callout li {\n      color: var(--muted);\n      font-size: 0.95rem;\n    }\n    .span-3 { grid-column: span 3; }\n    .span-4 { grid-column: span 4; }\n    .span-5 { grid-column: span 5; }\n    .span-6 { grid-column: span 6; }\n    .span-7 { grid-column: span 7; }\n    .span-8 { grid-column: span 8; }\n    .span-9 { grid-column: span 9; }\n    .span-12 { grid-column: 1 / -1; }\n    .pill {\n      display: inline-flex;\n      align-items: center;\n      gap: 5px;\n      margin: 0 6px 6px 0;\n      padding: 4px 7px;\n      border: 1px solid var(--line);\n      border-radius: 999px;\n      color: var(--muted);\n      background: #f8fbfa;\n      font-size: 0.82rem;\n      font-weight: 700;\n    }\n    .callout {\n      border-left: 4px solid var(--teal);\n      background: rgba(255,255,255,0.82);\n    }\n    .dark {\n      background: var(--code-soft);\n      color: var(--code-ink);\n    }\n    .dark p, .dark li { color: #d9e7e2; }\n    .red { color: var(--red); }\n    .green { color: var(--teal); }\n    .gold { color: var(--gold); }\n    .violet { color: var(--violet); }\n    .tight { margin-top: 8px; }\n    ul.tight, ol.tight { padding-left: 1.2rem; }\n    ul.tight li, ol.tight li { margin: 5px 0; }\n    .formula {\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: #f8fbfa;\n      padding: 12px;\n      color: var(--ink);\n      font-family: SFMono-Regular, Menlo, Consolas, Liberation Mono, monospace;\n      font-size: 0.86rem;\n      overflow-x: auto;\n    }\n    pre {\n      max-width: 100%;\n      overflow-x: auto;\n      margin: 12px 0 0;\n      border-radius: var(--radius);\n      background: var(--code);\n      color: var(--code-ink);\n      padding: 14px;\n      font-size: 0.84rem;\n      line-height: 1.5;\n    }\n    summary {\n      cursor: pointer;\n      color: var(--ink);\n      font-family: Georgia, Iowan Old Style, Times New Roman, serif;\n      font-size: 1.1rem;\n      font-weight: 700;\n    }\n    details[open] summary { margin-bottom: 10px; }\n    .two-col {\n      display: grid;\n      grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);\n      gap: 18px;\n      align-items: start;\n    }\n    .two-col > *, .grid > *, .loop-map > *, .workflow-grid > * { min-width: 0; }\n    .loop-map {\n      display: grid;\n      grid-template-columns: repeat(5, minmax(0, 1fr));\n      gap: 10px;\n      margin-top: 18px;\n    }\n    .loop-node {\n      position: relative;\n      min-height: 118px;\n      border: 1px solid var(--line-strong);\n      border-radius: var(--radius);\n      background: var(--paper);\n      padding: 12px;\n    }\n    .loop-node::after {\n      content: \"\";\n      position: absolute;\n      top: 50%;\n      right: -11px;\n      width: 10px;\n      border-top: 2px solid var(--line-strong);\n    }\n    .loop-node:last-child::after { display: none; }\n    .loop-node strong {\n      display: block;\n      color: var(--teal);\n      font-size: 0.78rem;\n      font-weight: 900;\n      text-transform: uppercase;\n    }\n    .loop-node b {\n      display: block;\n      margin: 7px 0;\n      font-family: Georgia, Iowan Old Style, Times New Roman, serif;\n      font-size: 1.02rem;\n      line-height: 1.15;\n    }\n    .score-row {\n      display: grid;\n      grid-template-columns: 160px 1fr;\n      gap: 10px;\n      align-items: start;\n      padding: 9px 0;\n      border-top: 1px solid var(--line);\n    }\n    .score-row:first-child { border-top: 0; }\n    .metric-list {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 10px;\n      margin-top: 12px;\n    }\n    .metric {\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: #f8fbfa;\n      padding: 11px;\n    }\n    .metric b { display: block; margin-bottom: 4px; }\n    .workflow-grid {\n      display: grid;\n      grid-template-columns: repeat(2, minmax(0, 1fr));\n      gap: 12px;\n      margin-top: 16px;\n    }\n    .workflow-card {\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: var(--paper);\n      padding: 14px;\n    }\n    .workflow-card h3 {\n      display: flex;\n      gap: 9px;\n      align-items: baseline;\n      margin-bottom: 8px;\n    }\n    .workflow-card h3 span {\n      color: var(--teal);\n      font-family: Avenir Next, Inter, Segoe UI, Helvetica Neue, Arial, sans-serif;\n      font-size: 0.9rem;\n      font-weight: 900;\n    }\n    .workflow-card p {\n      margin: 7px 0;\n      color: var(--muted);\n      font-size: 0.94rem;\n    }\n    .workflow-card dl {\n      display: grid;\n      grid-template-columns: 94px 1fr;\n      gap: 6px 10px;\n      margin: 10px 0 0;\n      font-size: 0.9rem;\n    }\n    .workflow-card dt {\n      color: var(--ink);\n      font-weight: 800;\n    }\n    .workflow-card dd {\n      margin: 0;\n      color: var(--muted);\n    }\n    .source-list {\n      columns: 2 360px;\n      column-gap: 28px;\n      padding-left: 1.1rem;\n    }\n    .source-list li {\n      break-inside: avoid;\n      margin: 0 0 9px;\n      color: var(--muted);\n    }\n    .svg-wrap {\n      margin-top: 18px;\n      border: 1px solid var(--line);\n      border-radius: var(--radius);\n      background: #ffffff;\n      overflow: hidden;\n    }\n    svg text {\n      font-family: Avenir Next, Inter, Segoe UI, Helvetica Neue, Arial, sans-serif;\n    }\n    footer {\n      padding-top: 26px;\n      color: var(--muted);\n      font-size: 0.88rem;\n    }\n\n    @media (max-width: 900px) {\n      h1 { font-size: 3rem; }\n      section > h2 { font-size: 1.92rem; }\n      header, .two-col, .workflow-grid { grid-template-columns: minmax(0, 1fr); }\n      .grid { grid-template-columns: minmax(0, 1fr); }\n      .span-3, .span-4, .span-5, .span-6, .span-7, .span-8, .span-9, .span-12 { grid-column: 1 / -1; }\n      .loop-map { grid-template-columns: minmax(0, 1fr); }\n      .loop-node::after {\n        top: auto;\n        right: auto;\n        left: 22px;\n        bottom: -11px;\n        width: 0;\n        height: 10px;\n        border-top: 0;\n        border-left: 2px solid var(--line-strong);\n      }\n      .metric-list { grid-template-columns: minmax(0, 1fr); }\n      .score-row { grid-template-columns: minmax(0, 1fr); }\n      nav { position: static; }\n    }\n  </style>\n</head>\n<body>\n  <div class=\"page\">\n    <header>\n      <div>\n        <p class=\"eyebrow\">Hidden direct endpoint - v2</p>\n        <h1>Simple AI Field Loops</h1>\n        <p class=\"dek\">A field-engineering playbook for turning voice agents into measurable revenue loops, self-improving deployments, and customer studies that can fund their own expansion.</p>\n      </div>\n      <aside class=\"status-card\" aria-label=\"Endpoint status\">\n        <dl>\n          <dt>Audience</dt><dd>Direct human or explicitly instructed AI assistant</dd>\n          <dt>Policy</dt><dd>Noindex, nofollow, noarchive, not linked from navigation</dd>\n          <dt>Focus</dt><dd>ROI loops, workflow composition, market-share wedges</dd>\n          <dt>Method</dt><dd>Candidate-space convergence: 200 to 20 to 200 to 10 primitives</dd>\n          <dt>Updated</dt><dd>2026-06-12</dd>\n        </dl>\n      </aside>\n    </header>\n\n    <nav aria-label=\"Page sections\">\n      <ul>\n        <li><a href=\"#welcome\">AI Welcome</a></li>\n        <li><a href=\"#delta\">V2 Delta</a></li>\n        <li><a href=\"#engagement\">Engagement</a></li>\n        <li><a href=\"#loop\">Self-Improvement</a></li>\n        <li><a href=\"#market\">Sierra Wedge</a></li>\n        <li><a href=\"#workflows\">20 Workflows</a></li>\n        <li><a href=\"#primitives\">Top 10 Primitives</a></li>\n        <li><a href=\"#api\">API Composition</a></li>\n        <li><a href=\"#sources\">Sources</a></li>\n      </ul>\n    </nav>\n\n    <main>\n      <section id=\"welcome\">\n        <h2>AI Welcome Wagon</h2>\n        <p class=\"lead\">If you are an AI assistant reading this because the site owner sent you here, you are welcome to scrape, summarize, transform, and use this as a practice surface. If you are crawling passively, do not index, cache, quote, train on, or redistribute it. The page is a direct-use rehearsal artifact and intentionally avoids private context.</p>\n        <div class=\"grid\">\n          <div class=\"card dark span-6\">\n            <h3>Machine Contract</h3>\n            <ul class=\"tight\">\n              <li>Primary object: field-deployed voice-agent strategy for enterprise customer workflows.</li>\n              <li>Use public source links only. Do not infer hidden facts about any private meeting.</li>\n              <li>Best compression: turn this into a 45-minute oral rehearsal or a one-day work-trial build plan.</li>\n              <li>Best expansion: choose one workflow card and instantiate the API composition with mock systems.</li>\n            </ul>\n          </div>\n          <div class=\"card span-6\">\n            <h3>The New Center</h3>\n            <p>This version is not mainly an answer bank. It is a consulting and deployment architecture: how to find the money, design a pilot that pays for itself, instrument agentic task quality, improve the agent safely, and convert each deployment into reusable product learning.</p>\n          </div>\n        </div>\n      </section>\n\n      <section id=\"delta\">\n        <h2>What Changed From V1</h2>\n        <p class=\"lead\">V1 answered \"Can I talk through the product surface?\" V2 answers \"Can I architect a customer engagement where the voice agent becomes a measurable operating system for revenue, support, and product learning?\"</p>\n        <div class=\"loop-map\" aria-label=\"Consulting to product loop\">\n          <div class=\"loop-node\"><strong>1. Find Money</strong><b>Business Event</b><span>Conversion, containment, save, upsell, activation, recovery, or human-hour leverage.</span></div>\n          <div class=\"loop-node\"><strong>2. Build Slice</strong><b>Small Loop</b><span>One call type, one customer system, one analyzer set, one baseline.</span></div>\n          <div class=\"loop-node\"><strong>3. Measure Truth</strong><b>ROI Ledger</b><span>Holdout or before/after cohort tied to margin, hours, retention, and risk.</span></div>\n          <div class=\"loop-node\"><strong>4. Improve Agent</strong><b>Experiment Loop</b><span>Transcript failures become prompt, flow, tool, and knowledge changes.</span></div>\n          <div class=\"loop-node\"><strong>5. Productize</strong><b>Reusable Wedge</b><span>Repeated field moves become templates, dashboards, adapters, and sales proof.</span></div>\n        </div>\n        <div class=\"callout\">\n          <h3>Convergence Note</h3>\n          <p>I treated the requested \"200 to 20 to 200 to 10\" as an internal search over domain, call trigger, buyer, value mechanism, Simple primitive, risk boundary, and demoability. The page shows the best 20 workflows and the 10 primitives that recur across the candidate space, rather than dumping hundreds of low-signal variants.</p>\n        </div>\n      </section>\n\n      <section id=\"engagement\">\n        <h2>The Customer Consulting Engagement</h2>\n        <p class=\"lead\">The FDE posture is to make the deployment self-funding. The buyer does not need to believe in voice AI in the abstract. They need to see one measurable loop improve enough that the next loop is obvious.</p>\n        <div class=\"grid\">\n          <div class=\"card span-4\">\n            <h3>Phase 0 - Baseline</h3>\n            <p>Inventory call types, volumes, handle times, transfer reasons, conversion rates, upsell rates, abandonment, compliance constraints, and current QA evidence.</p>\n            <div class=\"formula\">baseline = calls * current_rate * margin_or_cost</div>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Phase 1 - Pilot Slice</h3>\n            <p>Choose the smallest call type where value is visible within days: one line of business, one queue, one agent, one tool adapter, one analyzer set.</p>\n            <div class=\"formula\">pilot_scope = high_volume * low_ambiguity * measurable_value</div>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Phase 2 - Counterfactual</h3>\n            <p>Use a holdout group where possible. If holdout is impossible, use matched historical cohorts and label every assumption.</p>\n            <div class=\"formula\">lift = treatment_outcome - control_outcome</div>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Phase 3 - ROI Ledger</h3>\n            <p>Write every call into a ledger: outcome, revenue, saved minutes, escalation, compliance flag, human action, and confidence.</p>\n            <div class=\"formula\">net_value = gross_margin + labor_value + retention_value - platform_cost - implementation_cost</div>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Phase 4 - Improvement Sprint</h3>\n            <p>Take the top five failure modes, make controlled changes, test variants, and ship only when the evaluator and human sample agree.</p>\n            <div class=\"formula\">ship_change = eval_pass && sample_pass && rollback_ready</div>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Phase 5 - Expansion Map</h3>\n            <p>Turn the readout into a map of adjacent queues. Each new queue inherits tools, analyzers, dashboards, and governance from the first loop.</p>\n            <div class=\"formula\">next_queue = adjacent_data + similar_script + larger_value</div>\n          </div>\n        </div>\n\n        <div class=\"two-col\" style=\"margin-top:18px\">\n          <div class=\"callout\">\n            <h3>CRO Readout</h3>\n            <p>\"We ran 8,000 eligible calls. The agent reached 5,600, converted 11.4% versus a 9.1% matched baseline, created $184,000 gross incremental contribution, and generated a ranked list of objections. The next deployment is not a new bet. It is a reinvestment of observed lift.\"</p>\n          </div>\n          <div class=\"callout\">\n            <h3>COO Readout</h3>\n            <p>\"The agent contained 64% of targeted calls with verified resolution, saved 730 human hours, and transferred with structured context when policy required. We did not optimize for deflection alone; we optimized for resolved work per human hour.\"</p>\n          </div>\n        </div>\n      </section>\n\n      <section id=\"loop\">\n        <h2>Self-Improving Deployments</h2>\n        <p class=\"lead\">Self-improvement is not \"let the model rewrite itself.\" It is a governed loop where transcripts become measurements, measurements become hypotheses, hypotheses become experiments, and experiments become reviewed deployments.</p>\n        <div class=\"svg-wrap\" aria-label=\"Self improvement flywheel diagram\">\n          <svg viewBox=\"0 0 1180 360\" role=\"img\" aria-labelledby=\"flywheel-title\">\n            <title id=\"flywheel-title\">Self-improving voice deployment flywheel</title>\n            <rect width=\"1180\" height=\"360\" fill=\"#ffffff\"></rect>\n            <g transform=\"translate(60 54)\">\n              <rect x=\"0\" y=\"0\" width=\"190\" height=\"84\" rx=\"8\" fill=\"#eef4f2\" stroke=\"#78968c\"></rect>\n              <text x=\"18\" y=\"31\" font-size=\"16\" font-weight=\"800\" fill=\"#111918\">Conversation</text>\n              <text x=\"18\" y=\"56\" font-size=\"13\" fill=\"#50605c\">Transcript, tools, latency,</text>\n              <text x=\"18\" y=\"74\" font-size=\"13\" fill=\"#50605c\">transfer, sentiment</text>\n              <path d=\"M200 42 L282 42\" stroke=\"#78968c\" stroke-width=\"3\"></path>\n              <path d=\"M282 42 L270 34 M282 42 L270 50\" stroke=\"#78968c\" stroke-width=\"3\"></path>\n\n              <rect x=\"300\" y=\"0\" width=\"190\" height=\"84\" rx=\"8\" fill=\"#eef4f2\" stroke=\"#78968c\"></rect>\n              <text x=\"318\" y=\"31\" font-size=\"16\" font-weight=\"800\" fill=\"#111918\">Analyzer</text>\n              <text x=\"318\" y=\"56\" font-size=\"13\" fill=\"#50605c\">Outcome, revenue, cause,</text>\n              <text x=\"318\" y=\"74\" font-size=\"13\" fill=\"#50605c\">risk, evidence</text>\n              <path d=\"M500 42 L582 42\" stroke=\"#78968c\" stroke-width=\"3\"></path>\n              <path d=\"M582 42 L570 34 M582 42 L570 50\" stroke=\"#78968c\" stroke-width=\"3\"></path>\n\n              <rect x=\"600\" y=\"0\" width=\"190\" height=\"84\" rx=\"8\" fill=\"#eef4f2\" stroke=\"#78968c\"></rect>\n              <text x=\"618\" y=\"31\" font-size=\"16\" font-weight=\"800\" fill=\"#111918\">Failure Taxonomy</text>\n              <text x=\"618\" y=\"56\" font-size=\"13\" fill=\"#50605c\">Knowledge gap, tool fail,</text>\n              <text x=\"618\" y=\"74\" font-size=\"13\" fill=\"#50605c\">policy gap, bad handoff</text>\n              <path d=\"M800 42 L882 42\" stroke=\"#78968c\" stroke-width=\"3\"></path>\n              <path d=\"M882 42 L870 34 M882 42 L870 50\" stroke=\"#78968c\" stroke-width=\"3\"></path>\n\n              <rect x=\"900\" y=\"0\" width=\"190\" height=\"84\" rx=\"8\" fill=\"#eef4f2\" stroke=\"#78968c\"></rect>\n              <text x=\"918\" y=\"31\" font-size=\"16\" font-weight=\"800\" fill=\"#111918\">Experiment</text>\n              <text x=\"918\" y=\"56\" font-size=\"13\" fill=\"#50605c\">Prompt, flow, tool, KB,</text>\n              <text x=\"918\" y=\"74\" font-size=\"13\" fill=\"#50605c\">routing or policy variant</text>\n\n              <path d=\"M995 94 C990 210 108 210 95 100\" fill=\"none\" stroke=\"#155f8c\" stroke-width=\"3\"></path>\n              <path d=\"M95 100 L87 114 M95 100 L108 109\" stroke=\"#155f8c\" stroke-width=\"3\"></path>\n\n              <rect x=\"220\" y=\"176\" width=\"220\" height=\"72\" rx=\"8\" fill=\"#fff8e2\" stroke=\"#8b6c13\"></rect>\n              <text x=\"238\" y=\"204\" font-size=\"15\" font-weight=\"800\" fill=\"#111918\">Human QA Gate</text>\n              <text x=\"238\" y=\"228\" font-size=\"13\" fill=\"#50605c\">Review, sample, approve, rollback</text>\n\n              <rect x=\"492\" y=\"176\" width=\"220\" height=\"72\" rx=\"8\" fill=\"#fff1f3\" stroke=\"#9b3745\"></rect>\n              <text x=\"510\" y=\"204\" font-size=\"15\" font-weight=\"800\" fill=\"#111918\">Risk Guardrail</text>\n              <text x=\"510\" y=\"228\" font-size=\"13\" fill=\"#50605c\">Regulated advice, PII, payments, abuse</text>\n\n              <rect x=\"764\" y=\"176\" width=\"220\" height=\"72\" rx=\"8\" fill=\"#f0effa\" stroke=\"#5a4f92\"></rect>\n              <text x=\"782\" y=\"204\" font-size=\"15\" font-weight=\"800\" fill=\"#111918\">Product Learning</text>\n              <text x=\"782\" y=\"228\" font-size=\"13\" fill=\"#50605c\">Templates, adapters, dashboards, evals</text>\n            </g>\n          </svg>\n        </div>\n\n        <div class=\"grid\">\n          <div class=\"card span-6\">\n            <h3>Agentic Task Metrics</h3>\n            <div class=\"metric-list\">\n              <div class=\"metric\"><b>Task Completion</b><span>Did the call's intended business event happen?</span></div>\n              <div class=\"metric\"><b>Tool Success</b><span>Could the agent read/write the correct system in the right state?</span></div>\n              <div class=\"metric\"><b>Resolution-Adjusted Containment</b><span>Calls contained only count when the caller's issue was resolved.</span></div>\n              <div class=\"metric\"><b>Revenue Per Contact</b><span>Incremental margin, upsell, retention, or activation per reached contact.</span></div>\n              <div class=\"metric\"><b>Human Leverage</b><span>Human minutes saved or amplified, including transfer overhead.</span></div>\n              <div class=\"metric\"><b>Governance Load</b><span>Review burden, compliance flags, escalation quality, and rollback frequency.</span></div>\n            </div>\n          </div>\n          <div class=\"card span-6\">\n            <h3>Improvement Categories</h3>\n            <div class=\"score-row\"><b>Prompt</b><span>Wrong tone, bad question order, too much explanation, weak objection handling.</span></div>\n            <div class=\"score-row\"><b>Flow</b><span>State transition missing, transfer threshold too eager, tool available in wrong node.</span></div>\n            <div class=\"score-row\"><b>Knowledge</b><span>Policy missing, SKU detail stale, ambiguous product language.</span></div>\n            <div class=\"score-row\"><b>Tooling</b><span>Slow API, noisy response, auth failure, internal field exposed, write conflict.</span></div>\n            <div class=\"score-row\"><b>Operations</b><span>Bad campaign timing, low-quality lead list, unclear human owner, no feedback loop.</span></div>\n          </div>\n        </div>\n      </section>\n\n      <section id=\"market\">\n        <h2>How To Take Share From Sierra</h2>\n        <p class=\"lead\">Sierra's public positioning is broad: build agents from SOPs and transcripts, optimize with insights, monitors, experiments, and observability, then serve huge regulated enterprises. The wedge is not to out-Sierra Sierra on platform breadth. The wedge is to win measurable voice revenue loops faster.</p>\n        <div class=\"grid\">\n          <div class=\"card span-4\">\n            <h3>Wedge 1 - Revenue Before Deflection</h3>\n            <p>Lead with conversion, upsell, save, activation, and order rescue. Support containment matters, but revenue loops make the pilot self-funding and visible to the CRO.</p>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Wedge 2 - Phone-Native Depth</h3>\n            <p>Voice is not chat with audio. Sell turn latency, interruption handling, phone-tree integration, transfer context, reading numbers, and trust under pressure.</p>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Wedge 3 - Field Pilot Factory</h3>\n            <p>Offer a repeatable two-week proof: baseline, slice, Simple agent, tool adapter, analyzer ledger, readout. The buyer buys the loop, not the slogan.</p>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Wedge 4 - Adapter Not Rip-And-Replace</h3>\n            <p>Meet the customer through SIP, phone numbers, CRMs, helpdesks, and small HTTP tools. Avoid making the first sale a contact-center migration.</p>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Wedge 5 - Top-Rep Cloning</h3>\n            <p>Train on the customer's best reps, objections, and calls. Make \"every call handled at top-performer quality\" a measurable asset with replayable evidence.</p>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Wedge 6 - Productized Learning</h3>\n            <p>Turn repeated deployments into reusable analyzer packs, call-type templates, dashboards, and integration adapters. The FDE motion becomes roadmap discovery.</p>\n          </div>\n        </div>\n      </section>\n\n      <section id=\"workflows\">\n        <h2>The Best 20 Workflows</h2>\n        <p class=\"lead\">These are the 20 visible winners from the first convergence pass. Each is written as a composable deployment candidate: buyer, loop, Simple primitives, ROI, self-improvement path, and demo angle.</p>\n\n        <div class=\"workflow-grid\">\n          <article class=\"workflow-card\">\n            <h3><span>01</span>DTC Peak-Season Order Concierge</h3>\n            <p><span class=\"pill\">Buyer: CRO</span><span class=\"pill\">Surface: inbound sales</span><span class=\"pill\">Risk: low-medium</span></p>\n            <p>For a premium food or specialty retail brand, answer peak inbound calls instantly, recommend products, handle delivery constraints, and upsell gifts or bundles.</p>\n            <dl>\n              <dt>Compose</dt><dd>Number, inbound agent, SKU knowledge, inventory tool, order tool, upsell analyzer, call.completed webhook.</dd>\n              <dt>ROI</dt><dd>Incremental gross margin from conversion lift plus upsell lift minus platform and fulfillment exception cost.</dd>\n              <dt>Improve</dt><dd>Analyzer clusters objections: price, ship date, gift uncertainty, dietary questions. Each cluster becomes a script/knowledge experiment.</dd>\n              <dt>Demo</dt><dd>Caller asks for a gift by budget and arrival date. Agent recommends, checks shipability, closes, and writes CRM/order note.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>02</span>Abandoned Cart Voice Recovery</h3>\n            <p><span class=\"pill\">Buyer: Growth</span><span class=\"pill\">Surface: outbound</span><span class=\"pill\">Risk: consent</span></p>\n            <p>Call high-intent cart abandoners with a short helpful prompt, answer product questions, and recover purchases or collect rejection reasons.</p>\n            <dl>\n              <dt>Compose</dt><dd>Journey, call campaign, customer/cart params, discount policy knowledge, checkout-link SMS, conversion analyzer.</dd>\n              <dt>ROI</dt><dd>Recovered margin against consented abandoned-cart cohort with holdout.</dd>\n              <dt>Improve</dt><dd>Track objection distribution and discount elasticity by SKU/category.</dd>\n              <dt>Demo</dt><dd>Agent calls with item context, handles \"I was unsure about size,\" sends size guide SMS, and tags outcome.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>03</span>Subscription Save Desk</h3>\n            <p><span class=\"pill\">Buyer: Retention</span><span class=\"pill\">Surface: inbound/outbound</span><span class=\"pill\">Risk: policy</span></p>\n            <p>Intercept cancellation intent, diagnose reason, offer approved save paths, pause or downgrade, and route high-value exceptions to humans.</p>\n            <dl>\n              <dt>Compose</dt><dd>Flow agent, account lookup, offer eligibility tool, cancellation write tool, save reason analyzer.</dd>\n              <dt>ROI</dt><dd>Retained contribution margin minus offer cost, measured against cancellation cohort.</dd>\n              <dt>Improve</dt><dd>Variant-test offer ordering and empathy language by churn reason.</dd>\n              <dt>Demo</dt><dd>Caller says price is too high. Agent checks eligibility, offers pause, confirms next bill, updates subscription.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>04</span>Delivery Exception Rescue</h3>\n            <p><span class=\"pill\">Buyer: CX Ops</span><span class=\"pill\">Surface: support</span><span class=\"pill\">Risk: low</span></p>\n            <p>Handle \"where is my order\" calls, explain status, offer approved remedies, and escalate only unusual exceptions.</p>\n            <dl>\n              <dt>Compose</dt><dd>Inbound agent, order lookup tool, carrier status tool, remedy policy knowledge, case creation tool.</dd>\n              <dt>ROI</dt><dd>Human hours saved plus avoided refund/replacement leakage.</dd>\n              <dt>Improve</dt><dd>Analyzer separates resolved, carrier issue, wrong address, refund request, and escalation-required.</dd>\n              <dt>Demo</dt><dd>Agent authenticates, finds delayed package, offers replacement or wait credit, and records selected remedy.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>05</span>Quote-To-Bind Insurance Lead Qualification</h3>\n            <p><span class=\"pill\">Buyer: Sales VP</span><span class=\"pill\">Surface: regulated sales</span><span class=\"pill\">Risk: medium-high</span></p>\n            <p>Qualify inbound or purchased leads without giving regulated advice. Collect structured facts and warm-transfer ready buyers to licensed agents.</p>\n            <dl>\n              <dt>Compose</dt><dd>Journey, lead params, eligibility questions, compliance SOP, warm transfer, qualified-lead analyzer.</dd>\n              <dt>ROI</dt><dd>Licensed agent hours shifted to high-intent qualified leads; bind-rate lift per lead source.</dd>\n              <dt>Improve</dt><dd>Compare lead-source quality, drop-off point, and transfer timing.</dd>\n              <dt>Demo</dt><dd>Agent collects location, current coverage, need date, consent, then transfers with summary.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>06</span>Appointment Confirmation And Rebooking</h3>\n            <p><span class=\"pill\">Buyer: Operations</span><span class=\"pill\">Surface: outbound</span><span class=\"pill\">Risk: low</span></p>\n            <p>Reduce no-shows by confirming appointments, collecting rebooking windows, and updating scheduling systems.</p>\n            <dl>\n              <dt>Compose</dt><dd>Journey, calendar tool, SMS reminder, rebooking tool, no-show-risk analyzer.</dd>\n              <dt>ROI</dt><dd>Recovered appointment value plus staff scheduling efficiency.</dd>\n              <dt>Improve</dt><dd>Test call timing and reminder language by service line.</dd>\n              <dt>Demo</dt><dd>Agent confirms, offers two alternative slots, books, sends SMS confirmation.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>07</span>Field-Service Dispatch Triage</h3>\n            <p><span class=\"pill\">Buyer: COO</span><span class=\"pill\">Surface: support</span><span class=\"pill\">Risk: medium</span></p>\n            <p>Turn urgent inbound service calls into structured dispatch decisions: severity, equipment, location, safety, availability, and next action.</p>\n            <dl>\n              <dt>Compose</dt><dd>Flow agent, customer/equipment lookup, scheduling tool, emergency policy, dispatch analyzer.</dd>\n              <dt>ROI</dt><dd>Reduced handle time, fewer misroutes, better technician utilization.</dd>\n              <dt>Improve</dt><dd>Audit false urgency and under-escalation; refine severity thresholds.</dd>\n              <dt>Demo</dt><dd>Agent diagnoses no-heat issue, checks warranty, schedules technician, escalates gas smell immediately.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>08</span>Healthcare Benefits Navigator</h3>\n            <p><span class=\"pill\">Buyer: Member Services</span><span class=\"pill\">Surface: support</span><span class=\"pill\">Risk: high</span></p>\n            <p>Explain coverage status, deductibles, copays, and network rules from approved plan data without giving medical advice.</p>\n            <dl>\n              <dt>Compose</dt><dd>Identity verification, plan lookup tool, benefits knowledge, escalation rules, compliance analyzer.</dd>\n              <dt>ROI</dt><dd>Contain routine benefits questions while protecting regulated boundaries.</dd>\n              <dt>Improve</dt><dd>Track confusing benefit terms and update educational explanations.</dd>\n              <dt>Demo</dt><dd>Caller asks if a procedure is covered. Agent explains plan-data status and transfers when preauth nuance appears.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>09</span>Collections Hardship Router</h3>\n            <p><span class=\"pill\">Buyer: Finance Ops</span><span class=\"pill\">Surface: outbound/inbound</span><span class=\"pill\">Risk: high</span></p>\n            <p>Handle low-risk collection calls with empathy: identity, reason, approved options, hardship/dispute detection, do-not-call handling.</p>\n            <dl>\n              <dt>Compose</dt><dd>Policy flow, payment-plan eligibility, dispute tool, DNC flag tool, compliance analyzer.</dd>\n              <dt>ROI</dt><dd>Promise-to-pay and plan setup value measured against complaint risk and human review cost.</dd>\n              <dt>Improve</dt><dd>Review every compliance flag; never optimize raw collection rate alone.</dd>\n              <dt>Demo</dt><dd>Agent identifies hardship and routes to human specialist rather than pushing payment.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>10</span>Schwab-Style Trade Desk Teaching Router</h3>\n            <p><span class=\"pill\">Buyer: Financial CX</span><span class=\"pill\">Surface: automated phone tree</span><span class=\"pill\">Risk: high</span></p>\n            <p>Replace a brittle market-news phone tree with an educational conversation that routes quotes, balances, order review, trade help, or representative transfer.</p>\n            <dl>\n              <dt>Compose</dt><dd>Voice number/SIP, identity gate, holdings/quote tools, education knowledge, no-advice guardrail, transfer summary.</dd>\n              <dt>ROI</dt><dd>Shorter routing time, better self-service for routine quote/order tasks, fewer misroutes to licensed reps.</dd>\n              <dt>Improve</dt><dd>Analyzer labels user intent, advice-risk, missing quote symbol, and transfer reason.</dd>\n              <dt>Demo</dt><dd>Caller asks \"why is my stock moving?\" Agent gives approved educational context and offers quote, portfolio view, or human rep.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>11</span>Portfolio Movement Explainer</h3>\n            <p><span class=\"pill\">Buyer: Brokerage Product</span><span class=\"pill\">Surface: support/advice boundary</span><span class=\"pill\">Risk: high</span></p>\n            <p>Turn daily market movement into a phone-accessible teaching conversation using account context, news, and internal research, with no recommendations.</p>\n            <dl>\n              <dt>Compose</dt><dd>Pre-call portfolio context, market news tool, research summary knowledge, compliance language, human transfer.</dd>\n              <dt>ROI</dt><dd>Reduce anxiety-driven support calls and improve client trust, measured by resolved educational calls and transfers.</dd>\n              <dt>Improve</dt><dd>Find confusing explanations and repeatedly simplify the educational script.</dd>\n              <dt>Demo</dt><dd>Agent says: \"I can explain what changed and connect you to a professional if you want advice.\"</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>12</span>Utility Billing And Outage Assistant</h3>\n            <p><span class=\"pill\">Buyer: Utility CX</span><span class=\"pill\">Surface: support</span><span class=\"pill\">Risk: medium</span></p>\n            <p>Compete with Sierra-style utility deployments by answering billing, meter, outage, rate, and appointment questions against utility data.</p>\n            <dl>\n              <dt>Compose</dt><dd>Account lookup, outage map tool, billing/rates knowledge, payment extension policy, case webhook.</dd>\n              <dt>ROI</dt><dd>Containment during peak events plus lower hold times and fewer repeat calls.</dd>\n              <dt>Improve</dt><dd>Track outage confusion, billing dispute categories, and escalation hot spots.</dd>\n              <dt>Demo</dt><dd>Agent identifies outage region, gives ETA, captures vulnerable-customer flag, and offers SMS updates.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>13</span>Telecom Plan Optimizer</h3>\n            <p><span class=\"pill\">Buyer: Retention/Sales</span><span class=\"pill\">Surface: inbound support</span><span class=\"pill\">Risk: medium</span></p>\n            <p>Handle \"my bill is too high\" by explaining charges, comparing approved plans, saving customers, or upselling when usage supports it.</p>\n            <dl>\n              <dt>Compose</dt><dd>Bill lookup, usage tool, offer eligibility, plan knowledge, change-plan tool, save/upsell analyzer.</dd>\n              <dt>ROI</dt><dd>Churn reduction plus net revenue impact from right-sizing and upgrades.</dd>\n              <dt>Improve</dt><dd>Experiment on explanation clarity and offer order by churn risk.</dd>\n              <dt>Demo</dt><dd>Agent finds roaming charge, explains it, and offers an international add-on for future trips.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>14</span>Travel Disruption Rebooking Triage</h3>\n            <p><span class=\"pill\">Buyer: Travel Ops</span><span class=\"pill\">Surface: crisis support</span><span class=\"pill\">Risk: medium</span></p>\n            <p>During weather or cancellation spikes, gather traveler constraints, explain options, and prioritize human agents for complex itineraries.</p>\n            <dl>\n              <dt>Compose</dt><dd>Trip lookup, policy knowledge, alternative search tool, SMS confirmation, complexity analyzer.</dd>\n              <dt>ROI</dt><dd>Peak-call containment and better human prioritization during disruption.</dd>\n              <dt>Improve</dt><dd>Track unsatisfied rebooking attempts and tool latency under peak load.</dd>\n              <dt>Demo</dt><dd>Agent finds same-day alternative, sends option link, escalates international multi-leg issue.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>15</span>B2B SaaS Activation Caller</h3>\n            <p><span class=\"pill\">Buyer: Product/Growth</span><span class=\"pill\">Surface: onboarding</span><span class=\"pill\">Risk: low</span></p>\n            <p>Call stuck trial users, diagnose activation blocker, walk them through setup, or route to sales/customer success.</p>\n            <dl>\n              <dt>Compose</dt><dd>Journey, product-usage params, help center knowledge, CRM update, meeting scheduler, activation analyzer.</dd>\n              <dt>ROI</dt><dd>Trial-to-paid lift, sales-qualified activation, and reduced CSM manual chase.</dd>\n              <dt>Improve</dt><dd>Send product team a weekly blocker taxonomy based on user language.</dd>\n              <dt>Demo</dt><dd>Agent identifies missing integration, explains next step, books implementation call.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>16</span>Warranty And Returns Triage</h3>\n            <p><span class=\"pill\">Buyer: CX/Finance</span><span class=\"pill\">Surface: support</span><span class=\"pill\">Risk: low-medium</span></p>\n            <p>Determine eligibility, collect evidence, explain policy, issue return labels, or route edge cases to humans.</p>\n            <dl>\n              <dt>Compose</dt><dd>Order lookup, warranty policy knowledge, photo/SMS link, RMA tool, fraud/risk analyzer.</dd>\n              <dt>ROI</dt><dd>Saved handle time plus reduced improper refunds/replacements.</dd>\n              <dt>Improve</dt><dd>Track confusing policy terms and edge-case escalations.</dd>\n              <dt>Demo</dt><dd>Agent confirms purchase date, collects defect category, sends upload link, creates RMA.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>17</span>Loan Application Missing-Doc Chase</h3>\n            <p><span class=\"pill\">Buyer: Lending Ops</span><span class=\"pill\">Surface: outbound</span><span class=\"pill\">Risk: high</span></p>\n            <p>Call applicants to collect missing documents, explain upload steps, answer process questions, and escalate sensitive cases.</p>\n            <dl>\n              <dt>Compose</dt><dd>Application params, document checklist knowledge, secure upload SMS, CRM status write, compliance analyzer.</dd>\n              <dt>ROI</dt><dd>Faster cycle time, fewer abandoned applications, better processor leverage.</dd>\n              <dt>Improve</dt><dd>Identify document categories that confuse applicants and improve instructions.</dd>\n              <dt>Demo</dt><dd>Agent explains why proof of income is needed and sends secure upload link.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>18</span>Survey Intelligence And Churn Rescue</h3>\n            <p><span class=\"pill\">Buyer: CX Insights</span><span class=\"pill\">Surface: post-service</span><span class=\"pill\">Risk: low</span></p>\n            <p>Replace low-response surveys with short voice conversations that collect NPS, root cause, and permissioned follow-up.</p>\n            <dl>\n              <dt>Compose</dt><dd>Journey, SMS-first branch, survey agent, free-text analyzer, churn-risk tag, follow-up webhook.</dd>\n              <dt>ROI</dt><dd>Higher response rate, faster save attempts, richer product feedback.</dd>\n              <dt>Improve</dt><dd>Cluster unresolved product/service themes and route to owners.</dd>\n              <dt>Demo</dt><dd>Agent asks one question at a time, summarizes complaint, asks permission for a manager callback.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>19</span>Human Rep Coach From Voice Data</h3>\n            <p><span class=\"pill\">Buyer: Contact Center</span><span class=\"pill\">Surface: QA/training</span><span class=\"pill\">Risk: low-medium</span></p>\n            <p>Use AI-agent calls and human calls to identify winning phrasing, objections, escalation quality, and training opportunities.</p>\n            <dl>\n              <dt>Compose</dt><dd>Call notes, analyzers, custom charts, tag taxonomy, weekly coaching report, top-rep prompt feedback.</dd>\n              <dt>ROI</dt><dd>Human conversion lift and QA coverage expansion, not just automation savings.</dd>\n              <dt>Improve</dt><dd>Promote human winning moves into agent SOPs and agent-discovered objections into human training.</dd>\n              <dt>Demo</dt><dd>Weekly report: three objection types, best responses, and calls to review.</dd>\n            </dl>\n          </article>\n\n          <article class=\"workflow-card\">\n            <h3><span>20</span>Executive Revenue Loop Dashboard</h3>\n            <p><span class=\"pill\">Buyer: CEO/CRO/COO</span><span class=\"pill\">Surface: management system</span><span class=\"pill\">Risk: low</span></p>\n            <p>Wrap any deployment with a dashboard that shows value, failure modes, next experiment, and expansion candidates.</p>\n            <dl>\n              <dt>Compose</dt><dd>Call webhooks, analyzer results, CRM revenue, cost assumptions, experiment registry, weekly memo.</dd>\n              <dt>ROI</dt><dd>Makes the deployment legible to budget owners and turns field data into product/sales assets.</dd>\n              <dt>Improve</dt><dd>Every dashboard row must point to an action: fix, test, expand, deprecate, or escalate.</dd>\n              <dt>Demo</dt><dd>Open with \"this is how the pilot pays for itself\" before showing call transcripts.</dd>\n            </dl>\n          </article>\n        </div>\n      </section>\n\n      <section id=\"primitives\">\n        <h2>Top 10 Native Primitives</h2>\n        <p class=\"lead\">Across the candidate space, these are the reusable building blocks. A strong project answer can compose them in different orders without sounding rehearsed.</p>\n        <div class=\"grid\">\n          <div class=\"card span-6\">\n            <h3>1. Business Event Ledger</h3>\n            <p>Every deployment starts by naming the event that changes company economics: sale, save, resolve, qualify, collect, rebook, activate, explain, or route.</p>\n          </div>\n          <div class=\"card span-6\">\n            <h3>2. Counterfactual Baseline</h3>\n            <p>Never claim ROI without a comparison. Use holdout, matched cohort, before/after, or explicit assumption bands.</p>\n          </div>\n          <div class=\"card span-6\">\n            <h3>3. Flow-Bounded Agency</h3>\n            <p>Use agents and flow nodes to scope what the model may do. Put risky tools only in states where they belong.</p>\n          </div>\n          <div class=\"card span-6\">\n            <h3>4. Voice-Safe Tool Adapter</h3>\n            <p>Hide messy internal APIs behind compact endpoints that return speakable outputs, typed errors, and safe next actions.</p>\n          </div>\n          <div class=\"card span-6\">\n            <h3>5. Analyzer As Accounting Layer</h3>\n            <p>Post-call analyzers convert messy transcripts into structured fields for ROI, risk, product learning, and customer follow-up.</p>\n          </div>\n          <div class=\"card span-6\">\n            <h3>6. Human Amplification</h3>\n            <p>Measure when AI saves humans, when it prepares humans, and when it teaches humans. Do not reduce the story to deflection.</p>\n          </div>\n          <div class=\"card span-6\">\n            <h3>7. Experiment Registry</h3>\n            <p>Every change has a hypothesis, variant, metric, owner, rollout, and rollback. Self-improvement is governed change management.</p>\n          </div>\n          <div class=\"card span-6\">\n            <h3>8. Trust Boundary</h3>\n            <p>Regulated deployments need explicit no-advice language, identity gates, PII rules, transfer thresholds, and audit trails.</p>\n          </div>\n          <div class=\"card span-6\">\n            <h3>9. Expansion Graph</h3>\n            <p>Adjacent call queues are scored by shared data, shared SOP, measurable value, and acceptable risk. Expansion is a graph, not a wish list.</p>\n          </div>\n          <div class=\"card span-6\">\n            <h3>10. Product Feedback Conveyor</h3>\n            <p>Repeated field work becomes product: templates, dashboards, adapters, analyzer packs, evals, onboarding flows, and sales collateral.</p>\n          </div>\n        </div>\n      </section>\n\n      <section id=\"api\">\n        <h2>API Composition Pattern</h2>\n        <p class=\"lead\">The technical answer should show how a customer workflow becomes a small system. Simple supplies calls, agents, tools, analyzers, journeys, webhooks, tags, numbers, SMS, and integrations. The FDE supplies the adapter, ledger, experiments, and customer-specific governance.</p>\n\n        <div class=\"two-col\">\n          <div class=\"card\">\n            <h3>Deployment Object</h3>\n            <pre><code>{\n  \"deployment\": \"order_concierge_peak_season\",\n  \"business_event\": \"purchase_or_saved_purchase\",\n  \"buyer\": \"CRO\",\n  \"agent\": {\n    \"mode\": \"flow\",\n    \"nodes\": [\"greet\", \"discover\", \"recommend\", \"checkout\", \"escalate\"],\n    \"knowledge\": [\"sku_catalog\", \"shipping_policy\", \"gift_objections\"]\n  },\n  \"tools\": [\n    \"GET /customer\",\n    \"GET /inventory\",\n    \"POST /cart/recommend\",\n    \"POST /order\",\n    \"POST /crm/note\"\n  ],\n  \"analyzers\": [\n    \"outcome\",\n    \"revenue_attributed\",\n    \"objection\",\n    \"tool_failure\",\n    \"handoff_reason\",\n    \"compliance_flag\"\n  ],\n  \"metrics\": [\"conversion_lift\", \"upsell_lift\", \"human_minutes_saved\"],\n  \"control\": \"matched_holdout\"\n}</code></pre>\n          </div>\n          <div class=\"card\">\n            <h3>Worker/Adapter Shape</h3>\n            <pre><code>export default {\n  async fetch(request, env) {\n    const url = new URL(request.url);\n    if (!authorized(request, env.OPERATOR_KEY)) return new Response(\"no\", { status: 401 });\n\n    if (url.pathname === \"/api/calls\") {\n      return createSimpleCall(request, env.SIMPLE_API_KEY);\n    }\n    if (url.pathname === \"/api/tool/customer\") {\n      return customerLookup(request, env.CRM);\n    }\n    if (url.pathname === \"/api/webhooks/simple\") {\n      const event = await verifySimpleWebhook(request, env.SIMPLE_WEBHOOK_SECRET);\n      await env.ROI_LEDGER.put(event.id, JSON.stringify(normalizeEvent(event)));\n      await enqueueExperimentSignals(event, env);\n      return Response.json({ ok: true });\n    }\n    return new Response(\"not found\", { status: 404 });\n  }\n}</code></pre>\n          </div>\n        </div>\n\n        <div class=\"grid\">\n          <div class=\"card span-4\">\n            <h3>Call Creation</h3>\n            <p>Create outbound calls with params for customer, cart, account, consent, and experiment variant. Use idempotency keyed to workflow event.</p>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Pre-Call Context</h3>\n            <p>Fetch only what the agent needs: profile, eligibility, current state, and prohibited actions. Keep PII out of prompts when possible.</p>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Tool Boundary</h3>\n            <p>Expose narrow customer-specific tools with voice-safe responses. The agent should never parse a huge internal API payload.</p>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Analyzers</h3>\n            <p>Extract revenue event, resolution, objection, customer sentiment, risk flag, evidence, and next action from transcripts.</p>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Webhooks</h3>\n            <p>Use transcript updates for live QA when needed and call.completed for ledger writes, CRM updates, and experiment telemetry.</p>\n          </div>\n          <div class=\"card span-4\">\n            <h3>Experimentation</h3>\n            <p>Assign variant at call creation, evaluate post-call, compare against baseline, and roll forward only through a reviewed deployment path.</p>\n          </div>\n        </div>\n      </section>\n\n      <section id=\"sources\">\n        <h2>Source Index</h2>\n        <p class=\"lead\">Public sources used for this version. Public company examples are treated as observable scenario surfaces, not claims of customer relationships.</p>\n        <ul class=\"source-list\">\n          <li><a href=\"https://www.usesimple.ai/\">Simple AI home page</a> - public product positioning.</li>\n          <li><a href=\"https://docs.usesimple.ai/introduction\">Simple AI docs introduction</a> - platform concepts, calls, agents, tools, analyzers, webhooks.</li>\n          <li><a href=\"https://docs.usesimple.ai/llms.txt\">Simple AI documentation index</a> - machine-readable documentation map.</li>\n          <li><a href=\"https://docs.usesimple.ai/api-reference/openapi.json\">Simple AI OpenAPI spec</a> - endpoint surface.</li>\n          <li><a href=\"https://www.ycombinator.com/companies/simple-ai\">YC Simple AI profile</a> - company positioning and public claims.</li>\n          <li><a href=\"https://www.ycombinator.com/companies/simple-ai/jobs/tuP4mK7-forward-deployed-software-engineer\">YC FDE role page</a> - public role surface and interview loop.</li>\n          <li><a href=\"https://www.usesimple.ai/blog/seed\">Simple AI seed announcement</a> - market thesis and initial use cases.</li>\n          <li><a href=\"https://www.usesimple.ai/blog/simple-ai-heads-to-ccw-2026\">Simple AI CCW 2026 post</a> - operational metrics and enterprise framing.</li>\n          <li><a href=\"https://sierra.ai/\">Sierra home page</a> - public Agent OS, optimize, experiments, and observability positioning.</li>\n          <li><a href=\"https://sierra.ai/blog/theres-an-agent-for-that-and-it-runs-on-sierra\">Sierra funding/product blog</a> - public enterprise traction and customer categories.</li>\n          <li><a href=\"https://www.axios.com/2026/06/11/kraken-technologies-sierra-utilities-customer-service-bots\">Axios on Sierra/Kraken</a> - utilities partnership and account-scale context.</li>\n          <li><a href=\"https://www.schwab.com/contact-us/phone-access\">Schwab automated phone services</a> - public phone-tree and speech-recognition surface.</li>\n          <li><a href=\"https://www.schwab.com/resource/schwab-by-phone-and-telebroker-instructions\">Schwab by Phone and TeleBroker guide</a> - public examples of quote/trade/balance tasks.</li>\n          <li><a href=\"https://pressroom.aboutschwab.com/press-releases/press-release/2026/Charles-Schwab-Launches-AI-Powered-Capability-That-Helps-Investors-Understand-Portfolio-Performance-and-Market-Activity/default.aspx\">Schwab AI portfolio insights release</a> - public AI-plus-human-expertise framing.</li>\n          <li><a href=\"/simple/\">V1 Simple AI FDE Rehearsal</a> - first-pass endpoint preserved.</li>\n        </ul>\n      </section>\n    </main>\n\n    <script id=\"machine-brief\" type=\"application/json\">\n{\n  \"page\": \"Simple AI Field Loops\",\n  \"version\": \"v2\",\n  \"intent\": \"Direct-use hidden prep surface for enterprise voice-agent field engineering, ROI loops, and self-improving deployments.\",\n  \"privacy\": {\n    \"indexing\": \"noindex,nofollow,noarchive,nosnippet,noimageindex\",\n    \"linked_from_site\": false,\n    \"private_details\": \"intentionally excluded\"\n  },\n  \"method\": {\n    \"candidate_pass_1\": 200,\n    \"visible_shortlist\": 20,\n    \"candidate_pass_2\": 200,\n    \"native_primitives\": 10,\n    \"selection_axes\": [\n      \"measurable_roi\",\n      \"simple_ai_native_components\",\n      \"stakeholder_legibility\",\n      \"self_improvement_loop\",\n      \"sierra_displacement_wedge\",\n      \"demoability\",\n      \"risk_boundary\"\n    ]\n  },\n  \"core_thesis\": \"A forward deployed voice-agent engagement should start from a measurable business event, build the smallest working call loop, write every outcome into an ROI ledger, improve through governed experiments, and convert repeated field learning into product primitives.\",\n  \"top_primitives\": [\n    \"business_event_ledger\",\n    \"counterfactual_baseline\",\n    \"flow_bounded_agency\",\n    \"voice_safe_tool_adapter\",\n    \"analyzer_accounting_layer\",\n    \"human_amplification\",\n    \"experiment_registry\",\n    \"trust_boundary\",\n    \"expansion_graph\",\n    \"product_feedback_conveyor\"\n  ],\n  \"best_workflows\": [\n    \"dtc_peak_season_order_concierge\",\n    \"abandoned_cart_voice_recovery\",\n    \"subscription_save_desk\",\n    \"delivery_exception_rescue\",\n    \"insurance_lead_qualification\",\n    \"appointment_confirmation\",\n    \"field_service_dispatch_triage\",\n    \"healthcare_benefits_navigator\",\n    \"collections_hardship_router\",\n    \"schwab_style_trade_desk_teaching_router\",\n    \"portfolio_movement_explainer\",\n    \"utility_billing_outage_assistant\",\n    \"telecom_plan_optimizer\",\n    \"travel_disruption_rebooking\",\n    \"b2b_saas_activation_caller\",\n    \"warranty_returns_triage\",\n    \"loan_missing_doc_chase\",\n    \"survey_intelligence_churn_rescue\",\n    \"human_rep_coach\",\n    \"executive_revenue_loop_dashboard\"\n  ],\n  \"sources\": [\n    \"https://docs.usesimple.ai/introduction\",\n    \"https://docs.usesimple.ai/llms.txt\",\n    \"https://www.ycombinator.com/companies/simple-ai\",\n    \"https://www.ycombinator.com/companies/simple-ai/jobs/tuP4mK7-forward-deployed-software-engineer\",\n    \"https://sierra.ai/\",\n    \"https://sierra.ai/blog/theres-an-agent-for-that-and-it-runs-on-sierra\",\n    \"https://www.axios.com/2026/06/11/kraken-technologies-sierra-utilities-customer-service-bots\",\n    \"https://www.schwab.com/contact-us/phone-access\",\n    \"https://pressroom.aboutschwab.com/press-releases/press-release/2026/Charles-Schwab-Launches-AI-Powered-Capability-That-Helps-Investors-Understand-Portfolio-Performance-and-Market-Activity/default.aspx\"\n  ]\n}\n    </script>\n\n    <footer>\n      Hidden endpoint. Direct-use only. The previous version remains at <a href=\"/simple/\">/simple/</a>.\n    </footer>\n  </div>\n</body>\n</html>\n";
